import com.crowdin.client.core.http.exceptions.CrowdinApiException;
import com.crowdin.client.core.http.exceptions.HttpBadRequestException;
import com.crowdin.client.core.http.exceptions.HttpException;
import com.crowdin.client.sourcefiles.model.ExportOptions;
import com.crowdin.client.sourcefiles.model.FileInfo;
import com.crowdin.client.sourcefiles.model.ImportOptions;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import org.junit.Test;
import static org.junit.Assert.*;

public class JacksonJsonTransformerTest {

    @Test 
    public void parseValidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"key\":\"value\"}";
        try {
            Map result = transformer.parse(json, Map.class);
            assertEquals("value", result.get("key"));
        } catch (CrowdinApiException e) {
            fail("Expected no exception but caught: " + e.getMessage());
        }
    }

    @Test
    public void parseInvalidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"key\":\"value\"";
        try {
            Map result = transformer.parse(json, Map.class);
            fail("Expected an exception but none was thrown");
        } catch (CrowdinApiException e) {
            assertTrue(e instanceof HttpBadRequestException);
        }
    }

    @Test
    public void parseEmptyJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "";
        try {
            Map result = transformer.parse(json, Map.class);
            fail("Expected an exception but none was thrown");
        } catch (CrowdinApiException e) {
            assertTrue(e instanceof HttpException);
        }
    }

    @Test 
    public void convertValidObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Map<String, String> map = new HashMap<>();
        map.put("key", "value");
        try {
            String result = transformer.convert(map);
            assertEquals("{\"key\":\"value\"}", result);
        } catch (CrowdinApiException e) {
            fail("Expected no exception but caught: " + e.getMessage());
        }
    }

    @Test 
    public void convertNullObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Map<String, String> map = null;
        try {
            String result = transformer.convert(map);
            fail("Expected an exception but none was thrown");
        } catch (CrowdinApiException e) {
            assertTrue(e instanceof HttpException);
        }
    }
}
